        color: var(--muted);
        line-height: 1.6;
      }

      form {
        display: grid;
        gap: 20px;
      }

      .form-field {
        display: grid;
        gap: 8px;
      }

      label {
        font-weight: 600;
        font-size: 0.96rem;
      }

      input {
        width: 100%;
        border: 1px solid rgba(148, 163, 184, 0.22);
